local support = require('Frame.support')
---isInExcluded
local function isInExcluded(goodsId)
    local isIn = false
    ---极端服务器推送的情况下，正好在切场景
    if not isNull(UIModule.CurrentScreen) then
        local screenId = UIModule.CurrentScreen.Argument.id
        if screenId == Constants.UITypeIds.SceneLaunch then
            return true
        end
        local dialogs = UIModule.CurrentScreen.dialogs
        for i, dialog in support.list_ipairs(dialogs) do
            if table.keyof(excludedIds, dialog.Argument.id) then
                isIn = true
                break
            end
            -- 商城单独处理
            if dialog.Argument.id == Constants.UITypeIds.StoreEntry then
                if goodsId == Constants.Currency.FreeDiamondId then
                    isIn = true
                    break
                end
            end

            if dialog.Argument.id == Constants.UITypeIds.OverseaRenovaListDialog then
                isIn = true
                break
            end
        end
    end
    return isIn
end

--todo isBreakExcluded TMPForCatHouseExplore 
local function isBreakExcluded()
    local isIn = false
    ---极端服务器推送的情况下，正好在切场景
    if not isNull(UIModule.CurrentScreen) then
        local dialogs = UIModule.CurrentScreen.dialogs
        for i, dialog in support.list_ipairs(dialogs) do
            if table.keyof(tempEnablePlusBtnPanelList, dialog.Argument.id) then
                isIn = true
                break
            end
        end
    end
    return isIn
end

---FreshAssetByGoodsId
---
---@param goodsId number 道具id
---@param isIconUpdate boolean 是否更新icon图标
function AssetNodeMB:FreshAssetByGoodsId(goodsId, isIconUpdate)
    local ActionUtils = import('Game.UI.FightReady.UIMainChapter.ActionUtils')
    isIconUpdate = checkBool(isIconUpdate)
    if isIconUpdate then
        local photoPath = goodsConfMgr:GetPhotoPathSpecialById(goodsId)
        self.Icon.gameObject:EnsureComponent(typeof(CS.Engine.UI.ImageAlterable)):LoadSprite(photoPath)
        KTool.SetActive(self.Icon.gameObject, true)
    end
    goodsId = checkNumber(goodsId)

    self.goodsId = goodsId
    local isShowPlus = self:GetPlusIconStatus(goodsId)
    KTool.SetActive(self.PlusIcon.gameObject, isShowPlus)
    if goodsId == Constants.Currency.FreeDiamondId then
        local playerComp = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
        --self.Text_TMP.text = FormatCurrencyNum(checkNumber(playerComp.playerDojo.freeDiamond))
        self.Text_TMP.text = checkString(checkNumber(playerComp.playerDojo.freeDiamond))
    elseif goodsId == Constants.Currency.PayDiamondId then
        local playerComp = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
        self.Text_TMP.text = checkString(checkNumber(playerComp.playerDojo.diamond))
    elseif goodsId == Constants.Currency.MazeCurrency then
        local MazeMgr = import('Game.Maze.MazeMgr')
        self.Text_TMP.text = MazeMgr:GetInstance():GetMazeCurrencyNum()
    elseif self.goodsId == checkNumber(QuestConfMgr:GetInstance():GetTalentTicketId()) then
        local comp = GameUtils.GetEntityCompByType(ECSComponentType.Constants.TalentQuestComponent)
        self.Text_TMP.text = comp:GetCurTicketCount() .. "/" .. QuestConfMgr:GetInstance():GetTalentMaxTicketHave()
    elseif self.goodsId == checkNumber(ActionUtils.GetDailyQuestTicketId()) then
        self.Text_TMP.text = ActionUtils.GetDailyQuestCurTicketAddNum() .. "/" .. ActionUtils.GetDailyQuestMaxTicketNum()
    elseif goodsId == ActivityCakeUtils.GetActivityHpId()  then
        self.Text_TMP.text = ActivityCakeUtils.GetActivityHpNum()
    else
        local goodsNum = GoodsUtils.GetThingNo(goodsId)
        if self.goodsId == Constants.Currency.HpId then
            -- 體力時顯示
            local playerComp = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
            self.Text_TMP.text = table.concat({ goodsNum, "/", tostring(playerComp.playerDojo.hpLimit) }) --恢復體力上限
            KTool.SetActive(self.PlusIcon.gameObject, true)
        else
            self.Text_TMP.text = FormatCurrencyNum(goodsNum)
        end
    end

    SetButtonAction(self.PlusIcon, Bind(self, self.SetAction))  -- 加号图标也要可以点击，
    UIEventProxy.Create(self.controller.gameObject).onPointerClick = Bind(self, self.OnBtnGoodsInfo) -- 整个

end

--定制一个显示图标和数量
function AssetNodeMB:CustomByGoodsId(goodsId, text, cb)
    local photoPath = goodsConfMgr:GetPhotoPathSpecialById(goodsId)
    self.Icon.gameObject:EnsureComponent(typeof(ImageAlterable)):LoadSprite(photoPath)
    self.Text_TMP.text = text

    SetButtonAction(self.PlusIcon, function()
        if cb then
            cb()
        end
    end)  -- 加号图标也要可以点击，
    UIEventProxy.Create(self.controller.gameObject).onPointerClick = function()
        self:OnBtnGoodsInfo()
    end -- 整个
end

