---@param goodsId integer
---@return boolean
function AssetNodeMB:GetPlusIconStatus(goodsId)
    local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(goodsId)
    if vo and vo.isShowGotoIcon == false then
        return false
    end
    if FilterGoodIdMap[checkInt(goodsId)] then
        return false
    end
    if isInExcluded(goodsId) then
        return false
    end
    return true
end

function AssetNodeMB:OnDestroy()
    if self._co then
        cs_coroutine.stop(self._co)
        self._co = nil
    end

    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

