function AssetNodeMB:OnBtnGoodsInfo()
    if not self.canClick then
        return
    end
    local ActionUtils = import('Game.UI.FightReady.UIMainChapter.ActionUtils')
    local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(self.goodsId)
    if vo then
        xRecord.record('3-016', string.format('Click_currency_[%d]', self.goodsId))
        local midFestivalComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.ActivityMidFestivalComponent)
        local entryId = midFestivalComponent:GetActivityEnergyId()
        local screenId = UIModule.CurrentScreen.Argument.id
        if self.goodsId == Constants.Currency.HpId or self.goodsId == QuestConfMgr:GetInstance():GetTalentTicketId() then
            GameUtils.ShowCommonTipsBoardCountdown(self.Icon, vo.name, nil, nil, self.goodsId, true)
        elseif (self.goodsId == checkNumber(ActionUtils.GetDailyQuestTicketId()))
        or (self.goodsId == Constants.Currency.LadderStruggleTicket)
        or (self.goodsId == Constants.Currency.JackpotDungeon)
        or (self.goodsId == Constants.Currency.LadderStruggleSingleTicket)
        or (self.goodsId == checkNumber(ActivityCookingComponent:GetConfigParamsById(ActivityCookingConstants.ParamsDefine.HP_ITEM_ID))) then
            GameUtils.ShowCommonTipsBoardCountdown(self.Icon, vo.name, nil, nil, self.goodsId, true)
        elseif (self.goodsId == entryId) then
            ActivityMidFestivalUtils.ShowTipsCountDown(self.Icon, vo.name, nil, nil, self.goodsId, true)
        elseif DreamAdventuresMgr:GetActivityHPId() and checkInt(DreamAdventuresMgr:GetActivityHPId()) == self.goodsId then
            DreamAdventuresMgr:ShowTipsCountDown(self.Icon, vo.name, nil, nil, self.goodsId, true)
        elseif ParkourGameMgr:GetActivityHPId() and checkInt(ParkourGameMgr:GetActivityHPId()) == checkNumber(self.goodsId) then
            ---微缩世界的活动
            ParkourGameMgr:ShowTipsCountDown(self.Icon, vo.name, nil, nil, self.goodsId, true)
        elseif Constants.Currency.BambooHp == self.goodsId then
            ---@type BambooMgr
            local BambooMgr = import('Game.UI.FightReady.UIBamboo.BambooMgr'):GetInstance()
            BambooMgr:ShowTipsCountDown(self.Icon, vo.name, nil, nil, self.goodsId, true)
        elseif screenId == Constants.UITypeIds.UIMaidCoffeeEnterScene or screenId == Constants.UITypeIds.SceneLaunch then
            GameUtils.ShowCommonTipsBoard(self.Icon, vo.name, nil, nil, self.goodsId, true)
        elseif self.goodsId == Constants.Currency.Fairyland then
            GameUtils.ShowCommonTipsBoardCountdown(self.Icon, vo.name, nil, nil, self.goodsId, true)
        elseif self.goodsId == ActivityCakeUtils.GetActivityHpId() then
            GameUtils.ShowNewCommonTipsBoardCountdown(self.Icon, ActivityCakeUtils.GetActivityCakeMgr(), vo.name, nil, nil, self.goodsId, true)
        else
            --GameUtils.ShowCommonTipsBoard(self.Icon, vo.name, nil, nil, self.goodsId, true)
            GameUtils.ShowCommonGoodsTipsBoard(self.Icon, vo.id, true)
        end
    end
end

function AssetNodeMB:SetAction()
    if not self.canClick then
        return
    end
    local ActionUtils = import('Game.UI.FightReady.UIMainChapter.ActionUtils')
    local BattleCardGameUtils = import('Game.UI.BattleCardGame.BattleCardGameUtils')

    self._co = cs_coroutine.start(function()
        coroutine.yield(CS.UnityEngine.WaitForSeconds(0.2))
        KCookie.Set(Constants.IsOpnePageing, 0)
    end)
    
    local midFestivalComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.ActivityMidFestivalComponent)
    local entryId = midFestivalComponent:GetActivityEnergyId()
    ------------------------------------------------- [hp]
    if (self.goodsId == Constants.Currency.HpId) then
        if isBreakExcluded() or (not isInExcluded(self.goodsId)) then
            UIModule.OpenDialog({ id = Constants.UITypeIds.UIHPDialog })
        end

    ------------------------------------------------- [diamond]
    elseif (self.goodsId == Constants.Currency.PayDiamondId) then
        if not isInExcluded(self.goodsId) then
            local OverseaStoreUtils = import('Game.OverseaStore.OverseaStoreUtils')
            local excludeIds = {
                { id = UIModule.CurrentScreen:LastDialog().Argument.id }
            }
            OverseaStoreUtils.OpenStore(nil, excludeIds)
        end

    ------------------------------------------------- [天赋副本门票]
    elseif (self.goodsId == checkNumber(QuestConfMgr:GetInstance():GetTalentTicketId())) then
        --UIModule.OpenDialog({ id = Constants.UITypeIds.UITalentMaterialPurchaseDialog })
        local comp = GameUtils.GetEntityCompByType(ECSComponentType.Constants.TalentQuestComponent)
        local consumeId = QuestConfMgr:GetInstance():GetTalentTicketConsumeId()
        local consumeNum = QuestConfMgr:GetInstance():GetTalentTicketConsumeNum()
        local remainingTime = comp:GetRemainingTime()
        local buyTicketsTimes = comp:GetBuyTicketsTimes()
        local maxBuyTimes = QuestConfMgr:GetInstance():GetTalentTicketMaxBuy()
        local maxHaveNum = QuestConfMgr:GetInstance():GetTalentMaxTicketHave()
        local prices = {
            {
                current = consumeNum,
                currency = consumeId,
            }
        }
        local textLimit = localize("本周库存_num1_/_num2_", { _num1_ = maxBuyTimes - buyTicketsTimes, _num2_ = maxBuyTimes })
        local t = {
            goodsId = self.goodsId,
            prices = prices,
            remainTime = 0,
            haveNum = comp:GetCurTicketCount(),
            maxHaveNum = maxHaveNum,
            textLimit = textLimit,
            maxBuyNum = 1, --QuestConfMgr:GetInstance():GetTalentMaxTicketHave() - comp:GetCurTicketCount(),
            buyCb = function(num)
                comp:BuyTicketsReq()
            end,
        }
        UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonBuyItemDialog, parameters = t }, {})

    ------------------------------------------------- [日常门票]
    elseif (self.goodsId == checkNumber(ActionUtils.GetDailyQuestTicketId())) then
        UIModule.OpenDialog({id = Constants.UITypeIds.StoreDiamondExchangeDialog, parameters = {id = 5100021}})

    ------------------------------------------------- [天梯门票]
    elseif (self.goodsId == Constants.Currency.LadderTicket) then
        ---@type LadderParameterVo
        local vo = CfUtils.GetCfVo(AutoIds.IdSetting2560, 'LadderParameterVo', 19)
        if not vo then
            return
        end
        local data = {}
        local value = string.split(vo.num,':')
        data.consumeId = value[1]
        data.consumeNum = value[2]
        data.getId = 3000010
        data.getNum = 1
        data.interface = Interfaces.LADDER_TICKET
        data.remainNumFieldName = "ladderTicketResidueBuyTimes"     -- 剩余每日购买数量在playerDojo里的字段名
        UIModule.OpenDialog({id = Constants.UITypeIds.LadderCompetionExchangeOpals, parameters = data})

    ------------------------------------------------- [幻影斗技场门票]
    elseif (self.goodsId == Constants.Currency.LadderStruggleTicket) then
        ---@type LadderParameterVo
        local vo = CfUtils.GetCfVo(AutoIds.IdSetting4021, 'LadderParameterVo', 16)
        if not vo then
            return
        end
        local data = {}
        local value = string.split(vo.num,':')
        data.consumeId = value[1]
        data.consumeNum = value[2]
        data.getId = CfUtils.GetCfVo(AutoIds.IdSetting4021, 'LadderStruggleParamVo', 6).num
        data.getNum = 1
        data.interface = Interfaces.StruggleExchangeTicket
        data.callback = function()
            local playerComp = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
            local playerDojo = playerComp:GetPlayerDojo()
            local component = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.LadderStruggleComponent)
            component:SetCurTicketCount(playerDojo.asyncRecoverTicket)
        end
        UIModule.OpenDialog({id = Constants.UITypeIds.LadderCompetionExchangeOpals, parameters = data})

    ------------------------------------------------- [幻影训练场门票]
    elseif (self.goodsId == Constants.Currency.LadderStruggleSingleTicket) then
        ---@type LadderParameterVo
        local vo = CfUtils.GetCfVo(AutoIds.IdSetting4026, 'LadderParameterVo', 16)
        if not vo then
            return
        end
        local data = {}
        local value = string.split(vo.num,':')
