        ClubGVGUtils.ShowRebirthGoodsExchange()

    ------------------------------------------------- [巅峰竞猜券]
    elseif (self.goodsId == Constants.Currency.PVEQuizCurrencyId) then
    
    ------------------------------------------------- [钓鱼消耗品]
