        BambooMgr:BuyActivityHp()
        ------------------------------------------------- [梦境奇缘活动体力]
    elseif DreamAdventuresMgr:GetActivityHPId() and checkInt(DreamAdventuresMgr:GetActivityHPId()) == self.goodsId then
        DreamAdventuresMgr:BuyActivityHp()
    elseif ParkourGameMgr:GetActivityHPId() and checkInt(ParkourGameMgr:GetActivityHPId()) == checkNumber(self.goodsId) then
        ParkourGameMgr:BuyActivityHp()
    elseif self.goodsId == checkInt(ActivityCookingComponent:GetConfigParamsById(ActivityCookingConstants.ParamsDefine.HP_ITEM_ID)) then
        ---@type ActivityCookingComponent
        local ActivityCookingComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.ActivityCookingComponent)
        ActivityCookingComponent:BuyActivityHp()

    ------------------------------------------------- [和风战牌-体力]
    elseif self.goodsId == BattleCardGameUtils.GetHpGoodsId() then
        local battleCardGameComp = BattleCardGameUtils.GetComp()
        battleCardGameComp:ShowBuyActivityHp()
    
    elseif self.goodsId == ActivityCakeUtils.GetActivityHpId() then
        ActivityCakeUtils.ShowBuyActivityHp()
    ------------------------------------------------- [通用道具提示]
    else
        local vo = goodsConfMgr:GetGoodsVoById(self.goodsId)
        if isTable(vo) then
            local isShowNumText = not (self.goodsId == Constants.Currency.MazeCurrency)
            GameUtils.ShowCommonTipsBoard(self.Icon.gameObject, vo.name, vo.desc, vo.quality, self.goodsId, isShowNumText)
        end

        -- 暂时跳转的商城界面
        --local haveShop = false   -- 避免开启多次
        --for i, v in pairs(UIModule.CurrentScreen.dialogs) do
        --    if v.name == "ShopDiaLog" then
        --        haveShop = true
        --    end
        --end
        --if not haveShop then
        --    UIModule.OpenDialog({ id = Constants.UITypeIds.ShopDialog })
        --end
    end
end

function AssetNodeMB:SetCanClick(state)
    self.canClick = state
end

return AssetNodeMB